#include <iostream>
#include <map>
#include <utility>

using namespace std;

using ll = long long;
using pii = pair<ll, ll>;

map<pii, bool> cache;

bool gana(ll a, ll b) {
    if (b < a) swap(a, b);

    auto it = cache.find({a, b});
    if (it != cache.end()) return it->second;

    if (a == 0) return cache[{a, b}] = false;

    if (!gana(a, b % a))
        return cache[{a, b}] = true;

    for (ll k = a; k <= b;) {
        if (!gana(a, b - k))
            return cache[{a, b}] = true;

        if (k > b / a) break;
        k *= a;
    }

    return cache[{a, b}] = false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        ll a, b;
        cin >> a >> b;
        cout << (gana(a, b) ? "First\n" : "Second\n");
    }

    return 0;
}

